import fitz
doc = fitz.open('eprint/coupling_constraints.pdf')
page = doc[0]
draws = page.get_drawings()
for i,d in enumerate(draws):
    col = d.get('color'); fill=d.get('fill')
    def isred(c):
        return c and c[0]>0.8 and c[1]<0.4 and c[2]<0.4
    if isred(col) or isred(fill):
        pts=[]
        for it in d['items']:
            if it[0]=='l':
                pts.append(it[1]); pts.append(it[2])
            elif it[0]=='c':
                pts.append(it[1]); pts.append(it[4])
        xs=[p.x for p in pts]; ys=[p.y for p in pts]
        print(i, col, fill, d.get('dashes'), d.get('stroke_opacity'), d.get('fill_opacity'), 'npts',len(pts),
              'xr',(min(xs),max(xs)) if xs else None,'yr',(min(ys),max(ys)) if ys else None)
